import{_ as t,o as s,c as a,ah as n}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/architecture.md","filePath":"src/guide/architecture.md"}'),o={name:"guide/architecture.md"};function r(i,e,d,l,c,p){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Kura est une application <strong>Laravel monolithique</strong> rendue côté client par Inertia et Vue. Aucune API mobile dédiée : le mobile passe par l&#39;application Moodle de Sève.</p><h2 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Couche</th><th>Technologie</th></tr></thead><tbody><tr><td>Langage</td><td>PHP 8.3</td></tr><tr><td>Framework</td><td>Laravel 13</td></tr><tr><td>Rendu</td><td>Inertia v3 + Vue 3 (TypeScript)</td></tr><tr><td>Styles</td><td>Tailwind CSS v4, composants shadcn-vue, icônes Phosphor</td></tr><tr><td>Authentification web</td><td>Laravel Fortify (session, 2FA, passkeys) — pas d&#39;inscription publique</td></tr><tr><td>API</td><td>Laravel Sanctum (jetons)</td></tr><tr><td>OAuth2 / OIDC</td><td>Laravel Passport — Kura est le fournisseur d&#39;identité de Sève</td></tr><tr><td>Rôles</td><td><code>spatie/laravel-permission</code></td></tr><tr><td>PDF</td><td><code>barryvdh/laravel-dompdf</code></td></tr><tr><td>Tableurs</td><td><code>openspout/openspout</code></td></tr><tr><td>Routes typées</td><td>Laravel Wayfinder (front)</td></tr><tr><td>Tests</td><td>Pest 4, Pest Plugin Laravel</td></tr><tr><td>Qualité</td><td>Pint, Larastan niveau 7, ESLint, Prettier, <code>vue-tsc</code></td></tr><tr><td>Base</td><td>SQLite en local, MySQL en recette et production</td></tr></tbody></table><h2 id="vue-d-ensemble" tabindex="-1">Vue d&#39;ensemble <a class="header-anchor" href="#vue-d-ensemble" aria-label="Permalink to &quot;Vue d&#39;ensemble&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> Site NextBoxx (sans état)                                  Sève (Moodle LTS)</span></span>
<span class="line"><span>        │  POST /api/candidatures (clé d&#39;API)                ▲   │</span></span>
<span class="line"><span>        ▼                                                    │   │</span></span>
<span class="line"><span> ┌───────────────────────────────┐   OAuth2 / OIDC (SSO)     │   │</span></span>
<span class="line"><span> │ Kura (kura-web)               │◄──────────────────────────┘   │</span></span>
<span class="line"><span> │ Laravel + Inertia + Vue       │   Web services Moodle :        │</span></span>
<span class="line"><span> │ source de vérité admin/fin.   │   provisionnement, présence,   │</span></span>
<span class="line"><span> │                               │   notes, partenaires           │</span></span>
<span class="line"><span> │                               │───────────────────────────────►│</span></span>
<span class="line"><span> └───────────────────────────────┘◄───────────────────────────────┘</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> Email · WhatsApp · paiement en ligne · stockage privé des PDF</span></span></code></pre></div><p>Kura est la source de vérité pour l&#39;identité, les statuts, les candidatures, les inscriptions, la facturation, la certification et les rémunérations. Sève l&#39;est pour les contenus, la présence détaillée, les résultats et la messagerie.</p><h2 id="structure-du-depot" tabindex="-1">Structure du dépôt <a class="header-anchor" href="#structure-du-depot" aria-label="Permalink to &quot;Structure du dépôt&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app/</span></span>
<span class="line"><span>  Actions/            Actions Fortify et utilisateur</span></span>
<span class="line"><span>  Concerns/           Traits réutilisables (références annuelles, scellement PDF, règles de mot de passe)</span></span>
<span class="line"><span>  Console/Commands/   Commandes planifiées (billing:run, seve:sync, cohorts:advance…)</span></span>
<span class="line"><span>  Enums/              Statuts et typologies du domaine (≈ 60 enums)</span></span>
<span class="line"><span>  Http/Controllers/   Contrôleurs groupés par module (Admin, Billing, Cohorts, Documents…)</span></span>
<span class="line"><span>  Http/Middleware/    AuthenticateSiteKey, EnsureSeveAccess, SetLocale, HandleInertiaRequests</span></span>
<span class="line"><span>  Listeners/          Journalisation des connexions et des envois de notifications</span></span>
<span class="line"><span>  Models/             Modèles Eloquent (≈ 60)</span></span>
<span class="line"><span>  Notifications/      Notifications email, Sève et WhatsApp</span></span>
<span class="line"><span>  Providers/          AppServiceProvider : Gates, Passport, valeurs par défaut</span></span>
<span class="line"><span>  Services/           Logique métier extraite (documents, Sève, WhatsApp, reporting, direction)</span></span>
<span class="line"><span>routes/               Un fichier par module : web, api, oauth, billing, cohorts, documents…</span></span>
<span class="line"><span>resources/js/</span></span>
<span class="line"><span>  pages/              Pages Inertia (≈ 85), un dossier par module</span></span>
<span class="line"><span>  components/         Composants réutilisables (UI, candidatures, billing, cohortes…)</span></span>
<span class="line"><span>  layouts/            AppLayout, AuthLayout, PublicLayout…</span></span>
<span class="line"><span>  composables/        useAccess, useMainNav, useLocale, useAppearance…</span></span>
<span class="line"><span>  lib/                Formatage et libellés par domaine (billing.ts, enrolments.ts…)</span></span>
<span class="line"><span>  types/              Types TypeScript des props Inertia</span></span>
<span class="line"><span>  actions/ routes/    Fonctions Wayfinder générées</span></span>
<span class="line"><span>tests/</span></span>
<span class="line"><span>  Feature/            Tests HTTP et parcours métier, un dossier par module</span></span>
<span class="line"><span>  Unit/               Tests unitaires ciblés</span></span>
<span class="line"><span>deploy/cpanel/        Scripts de déploiement (install.sh, deploy.sh, crontab.example)</span></span></code></pre></div><h2 id="cycle-d-une-requete" tabindex="-1">Cycle d&#39;une requête <a class="header-anchor" href="#cycle-d-une-requete" aria-label="Permalink to &quot;Cycle d&#39;une requête&quot;">​</a></h2><ol><li><strong>Routage</strong> : les routes sont découpées par module dans <code>routes/</code>, puis chargées par <code>routes/web.php</code>.</li><li><strong>Middleware</strong> : <code>auth</code>, <code>verified</code>, <code>can:*</code>, <code>site.key</code> (API du site), <code>throttle:*</code>, <code>signed</code> (liens publics), <code>SetLocale</code>.</li><li><strong>Contrôleur</strong> : valide la requête (Form Requests), autorise l&#39;action (<code>Gate::authorize</code> ou <code>abort_unless</code>), exécute la logique métier et retourne une page Inertia ou un fichier.</li><li><strong>Props Inertia</strong> : <code>HandleInertiaRequests</code> partage l&#39;utilisateur, ses rôles et les booléens <code>can*</code> consommés par <code>useAccess</code>.</li><li><strong>Vue</strong> : la page reçoit des props typées, utilise les composants partagés et Wayfinder pour les URLs.</li></ol><h2 id="modele-de-donnees" tabindex="-1">Modèle de données <a class="header-anchor" href="#modele-de-donnees" aria-label="Permalink to &quot;Modèle de données&quot;">​</a></h2><p>Le modèle relationnel complet vit dans la documentation de référence. Les grands ensembles :</p><table tabindex="0"><thead><tr><th>Ensemble</th><th>Entités principales</th></tr></thead><tbody><tr><td>Comptes</td><td><code>User</code>, rôles spatie, demandes de rôle, transformations individu → organisation, journal d&#39;audit</td></tr><tr><td>Catalogue</td><td><code>Program</code> (référentiel), blocs de compétences, grille tarifaire, banque QCM et lots d&#39;import</td></tr><tr><td>Cohortes</td><td><code>Cohort</code>, affectations formateurs / coachs, jours fériés, séances</td></tr><tr><td>Admission</td><td><code>Candidature</code>, étapes, pièces, tentatives de test</td></tr><tr><td>Inscriptions</td><td><code>Enrolment</code>, conventions, versions de convention, consentements, financement</td></tr><tr><td>Facturation</td><td><code>Invoice</code>, <code>Payment</code>, <code>CreditNote</code>, rémunérations, commissions, contrats et factures marketing</td></tr><tr><td>Résultats</td><td>résultats par bloc, décisions de jury, certificats, attestations, relevés</td></tr><tr><td>Documents</td><td>conventions tripartites, conventions de stage, livrets d&#39;accueil, procès-verbaux de soutenance</td></tr><tr><td>Activités élargies</td><td>devis B2B, événements et inscriptions, demandes entreprises, profils, incubation, partenariats</td></tr><tr><td>Intégration</td><td>événements d&#39;intégration vers Sève, curseurs de synchronisation, livraisons de notifications</td></tr></tbody></table><p>Conventions structurantes :</p><ul><li>clés primaires entières auto-incrémentées ;</li><li>montants en FCFA, <code>DECIMAL(12,2)</code>, hors taxe ;</li><li>références lisibles et annuelles (<code>FAC-NB-AAAA-XXX</code>, <code>CONV-…</code>, <code>CERT-…</code>) générées par le trait <code>HasYearlyReference</code> ;</li><li>statuts portés par des enums PHP, jamais par des chaînes libres ;</li><li>documents PDF stockés sur disque privé, scellés par une empreinte SHA-256.</li></ul><h2 id="autorisation" tabindex="-1">Autorisation <a class="header-anchor" href="#autorisation" aria-label="Permalink to &quot;Autorisation&quot;">​</a></h2><p>L&#39;autorisation est centralisée dans <code>AppServiceProvider</code> sous forme de <strong>Gates</strong> nommés (<code>view-cohorts</code>, <code>manage-billing</code>, <code>manage-incubation</code>…), alimentés par les rôles spatie. Le front consomme les mêmes décisions via les props <code>can*</code> partagées par Inertia et le composable <code>useAccess</code>.</p><p>Trois niveaux coexistent :</p><ul><li><strong>middleware de route</strong> (<code>can:manage-cohorts</code>) pour bloquer une section entière ;</li><li><strong><code>Gate::authorize</code></strong> dans les contrôleurs pour les actions fines ;</li><li><strong><code>abort_unless</code></strong> dans quelques contrôleurs, lorsque la règle dépend de la ressource et non du rôle.</li></ul><p>Il n&#39;y a pas de Policies par modèle : le choix assume des Gates transverses. Voir <a href="/kura-guide/guide/development.html#points-de-vigilance">Développement</a> pour les garde-fous à respecter.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li><strong>Pages</strong> dans <code>resources/js/pages</code>, un dossier par module, rendues par <code>Inertia::render</code>.</li><li><strong>Composants</strong> partagés dans <code>resources/js/components</code> : UI (boutons, cartes, tableaux), marqueurs d&#39;étapes, tableaux de factures, filtres segmentés.</li><li><strong>Composables</strong> : <code>useAccess</code> (droits), <code>useMainNav</code> (menu et groupes), <code>useLocale</code>, <code>useAppearance</code>, <code>useCurrentUrl</code>.</li><li><strong>i18n</strong> : <code>vue-i18n</code>, messages dans <code>resources/js/lib/locales</code>, locale pilotée par <code>SetLocale</code> et le profil.</li><li><strong>Wayfinder</strong> : les URLs et actions sont importées depuis <code>@/actions</code> et <code>@/routes</code>, jamais écrites à la main.</li><li><strong>Design system</strong> : palette forêt / vert / or, typographie Plus Jakarta Sans, barre latérale pleine hauteur, badges d&#39;état colorés.</li></ul><h2 id="services-et-traits" tabindex="-1">Services et traits <a class="header-anchor" href="#services-et-traits" aria-label="Permalink to &quot;Services et traits&quot;">​</a></h2><p>La logique qui ne tient pas dans un modèle vit dans <code>app/Services</code> :</p><table tabindex="0"><thead><tr><th>Service</th><th>Rôle</th></tr></thead><tbody><tr><td><code>Documents/DocumentLibrary</code></td><td>Recense les documents d&#39;un compte pour « Mes documents »</td></tr><tr><td><code>Documents/CohortCalendar</code></td><td>Construit le calendrier d&#39;une cohorte</td></tr><tr><td><code>Seve/MoodleClient</code></td><td>Appels REST aux web services Moodle</td></tr><tr><td><code>WhatsApp/WhatsAppClient</code></td><td>Envoi de modèles WhatsApp Cloud API</td></tr><tr><td><code>Catalogue/QcmImporter</code></td><td>Import et validation des banques QCM</td></tr><tr><td><code>Direction/ActivityOverview</code></td><td>Agrégats du tableau de bord Direction</td></tr><tr><td><code>Reporting/ActivityReport</code></td><td>Indicateurs et export CSV du reporting</td></tr><tr><td><code>Partnerships/SevePartnersBlock</code></td><td>Bloc « Partenaires » écrit dans le résumé du cours Sève</td></tr><tr><td><code>Auth/TwoFactorTicketBroker</code></td><td>Tickets temporaires de la double authentification</td></tr></tbody></table><p>Les traits <code>HasYearlyReference</code>, <code>SealsPdf</code>, <code>PasswordValidationRules</code>, <code>ProfileValidationRules</code> et <code>AvatarValidationRules</code> portent les comportements transverses.</p><h2 id="points-de-vigilance" tabindex="-1">Points de vigilance <a class="header-anchor" href="#points-de-vigilance" aria-label="Permalink to &quot;Points de vigilance&quot;">​</a></h2><p>Quelques choix hérités méritent attention lors d&#39;une évolution :</p><ul><li>certains modèles sont volumineux (<code>Enrolment</code>, <code>Invoice</code>, <code>Cohort</code>, <code>CompanyRequest</code>) et mêlent requêtes, règles métier et formatage ;</li><li>les pages liste doivent charger leurs agrégats avec <code>withCount</code> / <code>withSum</code> plutôt qu&#39;en appelant des méthodes par ligne (risque de N+1) ;</li><li>la numérotation annuelle et les paiements s&#39;appuient sur des contraintes d&#39;unicité et des transactions : conserver les verrous et prévoir un rejeu en cas de collision ;</li><li>les payloads Inertia sont des tableaux construits à la main, dupliqués dans <code>resources/js/types</code> : les faire évoluer ensemble.</li></ul>`,30)])])}const h=t(o,[["render",r]]);export{m as __pageData,h as default};
